const scopedQuery =
  'MATCH (p:Party {id: $pid})-[:SIGNED]->(f:Filing {matter: $matter}) ' +
  '-[:CITES]->(s:Statute) ' +
  'RETURN p.name AS signer, f.id AS filing, s.id AS statute, f.text AS quote';
// $matter is bound from the investigator's open matter, server-side.

steps.infrastructure:
// The matter id constrains the pattern itself: a Filing node only matches
// when its matter attribute equals the open matter. The filter is in the
// walk, not in application code after it — by the time a post-walk filter
// runs, the other matter's text is already in memory and one slip quotes
// it. A shared party name is not a shared matter.

